function FindMaxSplit(task \(\tau_i\), processor \(P_k\), existing_tasks \(\tau(P_k)\)):
    // Assume a feasibility test function is_feasible(task, processor_tasks)
    max_x = 0
    for x from C_i down to 1:
        subtask1 = (x, x, T_i)
        if is_feasible(subtask1, \(\tau(P_k)\)):
            max_x = x
            break
    return max_x

function MigrateAvoidance(job_of_\(\tau_i\), subtask1_completion_time, subtask1_budget, subtask2_budget):
    if subtask1_completion_time < subtask1_budget:
        slack = subtask1_budget - subtask1_completion_time
        // CASH reclaims slack and awards it to the next eligible reservation
        // If \(\tau_{i2}\) is eligible and can use the slack:
        if \(\tau_{i2}\) can complete with slack:
            // Job completes, migration avoided
            return True
    return False
